def choose_move(observation):
    x, y = observation['self_position']
    ox, oy = observation['opponent_position']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    res_positions = [tuple(r) for r in resources]
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_dist = float('inf')
    for res in res_positions:
        d = dist((x,y), res)
        if d < min_dist:
            min_dist, target = d, res
    if target:
        dx = 0
        if target[0] > x: dx = 1
        elif target[0] < x: dx = -1
        dy = 0
        if target[1] > y: dy = 1
        elif target[1] < y: dy = -1
        next_pos = (x+dx, y+dy)
        if next_pos in obstacles or not (0 <= next_pos[0] < observation['grid_width']) or not (0 <= next_pos[1] < observation['grid_height']):
            dx, dy = 0, 0
        return [dx, dy]
    dx, dy = 0, 0
    # Move towards opponent if close
    ox_d, oy_d = ox - x, oy - y
    if abs(ox_d) > abs(oy_d):
        dx = 1 if ox_d > 0 else -1
        if (x+dx, y) in obstacles or not (0 <= x+dx < observation['grid_width']):
            dx = 0
    else:
        dy = 1 if oy_d > 0 else -1
        if (x, y+dy) in obstacles or not (0 <= y+dy < observation['grid_height']):
            dy = 0
    if dx == 0 and dy == 0:
        if (x+1 < observation['grid_width']) and (x+1, y) not in obstacles:
            dx = 1
        elif (x-1 >= 0) and (x-1, y) not in obstacles:
            dx = -1
        elif (x, y+1 < observation['grid_height']) and (x, y+1) not in obstacles:
            dy = 1
        elif (x, y-1 >=0) and (x, y-1) not in obstacles:
            dy = -1
    return [dx, dy]
